# Railway can run this file directly without a separate requirements.txt.
# Missing runtime libraries are installed on first start.
def _ensure_dependency(module_name: str, pip_name: str):
    try:
        if importlib.util.find_spec(module_name) is not None:
            return
    except (ImportError, ValueError, ModuleNotFoundError):
        pass
    print(f"[SETUP] Installing missing dependency: {pip_name}", flush=True)
    subprocess.check_call([
        sys.executable, "-m", "pip", "install",
        "--disable-pip-version-check", pip_name
    ])

for _module, _package in [
    ("httpx", "httpx"),
    ("requests", "requests"),
    ("Crypto", "pycryptodome"),
    ("google_play_scraper", "google-play-scraper"),
    ("protobuf_decoder", "protobuf-decoder"),
    ("aiohttp", "aiohttp"),
]:
    _ensure_dependency(_module, _package)

# The generated protobuf file requires protobuf runtime 7.35.1 or newer.
subprocess.check_call([
    sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
    "--upgrade", "protobuf>=7.35.1"
])

